        for j in range(i + 1, n):
            if s[i] < s[j]:
                visited.add(grundy[j])
        for g in range(n):
            if g not in visited:
                grundy[i] = g
                break

    # Determine the winner for each k
    for k in range(n):
        if grundy[k] > 0:
            winners.append('Ann')
        else:
            winners.append('Mike')

    return winners

